/// 正文基础字号 (CSS px, 2560×1440 舞台): `#root` 的 160% × 16px = 25.6px,
/// 再乘 WebGAL `getTextSize()` 的百分比 (small 155 / medium 205 / large 230)。
float font_px(std::string_view name) {
    float percent = 205.0F;
    if (name == "large") {
        percent = 230.0F;
    } else if (name == "small") {
        percent = 155.0F;
    }
    return 25.6F * percent / 100.0F;
}

std::vector<int> utf8_codepoints(std::string_view text) {
    std::vector<int> codepoints;
    for (std::size_t index = 0; index < text.size();) {
        const auto first = static_cast<unsigned char>(text[index]);
        int codepoint = 0;
        std::size_t length = 1;
        if ((first & 0x80U) == 0) {
            codepoint = first;
        } else if ((first & 0xE0U) == 0xC0U && index + 1 < text.size()) {
            codepoint = (first & 0x1FU) << 6;
            codepoint |= static_cast<unsigned char>(text[index + 1]) & 0x3FU;
            length = 2;
        } else if ((first & 0xF0U) == 0xE0U && index + 2 < text.size()) {
            codepoint = (first & 0x0FU) << 12;
            codepoint |= (static_cast<unsigned char>(text[index + 1]) & 0x3FU) << 6;
            codepoint |= static_cast<unsigned char>(text[index + 2]) & 0x3FU;
            length = 3;
        } else if ((first & 0xF8U) == 0xF0U && index + 3 < text.size()) {
            codepoint = (first & 0x07U) << 18;
            codepoint |= (static_cast<unsigned char>(text[index + 1]) & 0x3FU) << 12;
            codepoint |= (static_cast<unsigned char>(text[index + 2]) & 0x3FU) << 6;
            codepoint |= static_cast<unsigned char>(text[index + 3]) & 0x3FU;
            length = 4;
        } else {
            codepoint = '?';
        }
        codepoints.push_back(codepoint);
        index += length;
    }
    return codepoints;
}

/// 把 codepoint 写回 UTF-8 (自动换行时按字符重建行)。
std::string utf8_from_codepoint(int codepoint) {
    std::string text;
    if (codepoint < 0x80) {
        text.push_back(static_cast<char>(codepoint));
    } else if (codepoint < 0x800) {
        text.push_back(static_cast<char>(0xC0 | (codepoint >> 6)));
        text.push_back(static_cast<char>(0x80 | (codepoint & 0x3F)));
    } else if (codepoint < 0x10000) {
        text.push_back(static_cast<char>(0xE0 | (codepoint >> 12)));
        text.push_back(static_cast<char>(0x80 | ((codepoint >> 6) & 0x3F)));
        text.push_back(static_cast<char>(0x80 | (codepoint & 0x3F)));
    } else {
        text.push_back(static_cast<char>(0xF0 | (codepoint >> 18)));
        text.push_back(static_cast<char>(0x80 | ((codepoint >> 12) & 0x3F)));
        text.push_back(static_cast<char>(0x80 | ((codepoint >> 6) & 0x3F)));
        text.push_back(static_cast<char>(0x80 | (codepoint & 0x3F)));
    }
    return text;
}

std::string line_text(const job::TextLine& line) {
    std::string text;
    for (const auto& character : line.chars) {
        text += character.text;
    }
    return text;
}

bool read_text_file(const std::filesystem::path& path, std::string& text) {
    std::ifstream input(path, std::ios::binary);
    if (!input) {
        return false;
    }
    text.assign(std::istreambuf_iterator<char>(input), std::istreambuf_iterator<char>());
    return true;
}

std::string strip_css_comments(std::string css) {
    std::istringstream stream(css);
    std::string line;
    std::string result;
    while (std::getline(stream, line)) {
        if (const auto comment = line.find("//"); comment != std::string::npos) {
            line.erase(comment);
        }
        result += line;
        result += '\n';
    }
    return result;
}
std::string css_block(const std::string& css, const std::string& selector) {
    auto start = css.find(selector);
    while (start != std::string::npos) {
        const auto next = css.find_first_not_of(" \t\r\n", start + selector.size());
        if (next != std::string::npos && css[next] == '{') {
            break;
        }
        start = css.find(selector, start + selector.size());
    }
    if (start == std::string::npos) {
        return {};
    }
    const auto open = css.find('{', start + selector.size());
    if (open == std::string::npos) {
        return {};
    }
    int depth = 0;
    for (auto index = open; index < css.size(); ++index) {
        if (css[index] == '{') {
            ++depth;
        } else if (css[index] == '}') {
            if (--depth == 0) {
                return css.substr(open + 1, index - open - 1);
            }
        }
    }
    return {};
}

std::string css_value(const std::string& block, const std::string& key) {
    if (key.empty()) {
        return {};
    }
    int depth = 0;
    for (std::size_t index = 0; index + key.size() <= block.size(); ++index) {
        if (block[index] == '{') {
            ++depth;
            continue;
        }
        if (block[index] == '}') {
            --depth;
            continue;
        }
        if (depth != 0 || block.compare(index, key.size(), key) != 0) {
            continue;
        }
        const bool word_start =
            index == 0 || (!std::isalnum(static_cast<unsigned char>(block[index - 1])) &&
                           block[index - 1] != '-' && block[index - 1] != '_');
        const auto colon = block.find_first_not_of(" \t\r\n", index + key.size());
        if (word_start && colon != std::string::npos && block[colon] == ':') {
            const auto end = block.find_first_of(";}", colon + 1);
            return block.substr(colon + 1, end - colon - 1);
        }
    }
    return {};
}
float css_px(const std::string& block, const std::string& key, float fallback) {
    const std::string value = css_value(block, key);
    const auto position = value.find("px");
    if (position == std::string::npos) {
        return fallback;
    }
    try {
        return std::stof(value.substr(0, position));
    } catch (...) {
        return fallback;
    }
}

std::array<float, 4> css_color(const std::string& value, std::array<float, 4> fallback) {
    std::string text = value;
    text.erase(std::remove_if(text.begin(), text.end(),
                              [](unsigned char character) { return std::isspace(character) != 0; }),
               text.end());
    if (text.empty()) {
        return fallback;
    }
    if (text.rfind("transparent", 0) == 0) {
        return {0.0F, 0.0F, 0.0F, 0.0F};
    }
    if (text.rfind("white", 0) == 0) {
        return {1.0F, 1.0F, 1.0F, 1.0F};
    }
    if (text.rfind("black", 0) == 0) {
        return {0.0F, 0.0F, 0.0F, 1.0F};
    }
    if (text[0] == '#') {
        if (text.size() >= 7) {
            const auto red = std::strtol(text.substr(1, 2).c_str(), nullptr, 16) / 255.0F;
            const auto green = std::strtol(text.substr(3, 2).c_str(), nullptr, 16) / 255.0F;
            const auto blue = std::strtol(text.substr(5, 2).c_str(), nullptr, 16) / 255.0F;
            const auto alpha = text.size() >= 9
                                   ? std::strtol(text.substr(7, 2).c_str(), nullptr, 16) / 255.0F
                                   : 1.0F;
            return {red, green, blue, alpha};
        }
        if (text.size() >= 4) {
            const auto red = std::strtol(text.substr(1, 1).c_str(), nullptr, 16) / 15.0F;
            const auto green = std::strtol(text.substr(2, 1).c_str(), nullptr, 16) / 15.0F;
            const auto blue = std::strtol(text.substr(3, 1).c_str(), nullptr, 16) / 15.0F;
            return {red, green, blue, 1.0F};
        }
        return fallback;
    }
    const auto open = text.find('(');
    const auto close = text.find(')', open);
    if (open != std::string::npos && close != std::string::npos) {
        std::string body = text.substr(open + 1, close - open - 1);
        std::vector<float> values;
        std::size_t start = 0;
        while (start < body.size()) {
            const auto comma = body.find(',', start);
            try {
                values.push_back(std::stof(body.substr(start, comma - start)));
            } catch (...) {
                return fallback;
            }
            if (comma == std::string::npos) {
                break;
            }
            start = comma + 1;
        }
        if (values.size() >= 3) {
            const float alpha = values.size() >= 4 ? values[3] : 1.0F;
            return {values[0] / 255.0F, values[1] / 255.0F, values[2] / 255.0F, alpha};
        }
    }
    return fallback;
}

std::array<float, 4> css_color_at(const std::string& value, std::size_t start,
                                  std::array<float, 4> fallback) {
    const auto parenthesis = value.find('(', start);
    const auto end = value.find(')', parenthesis);
    if (parenthesis == std::string::npos || end == std::string::npos) {
        return fallback;
    }
    return css_color(value.substr(parenthesis, end - parenthesis + 1), fallback);
}

std::vector<std::string> css_tokens(const std::string& value) {
    std::istringstream stream(value);
    std::vector<std::string> tokens;
    std::string token;
    while (stream >> token) {
        tokens.push_back(token);
    }
    return tokens;
}

/// `"1.7em"` → 1.7; 没有 em 单位时返回 fallback。
float css_em_ratio(const std::string& value, float fallback) {
    const auto position = value.find("em");
    if (position == std::string::npos) {
        return fallback;
    }
    try {
        return std::stof(value.substr(0, position));
    } catch (...) {
        return fallback;
    }
}

/// 解析一个纯数字 (例如 `scale: 1.25`)。
float css_number(const std::string& value, float fallback) {
    if (value.empty()) {
        return fallback;
    }
    try {
        return std::stof(value);
    } catch (...) {
        return fallback;
    }
}

/// 解析单个 token 里的 px 数值 (例如 `"125px"`)。
float css_px_text(const std::string& value, float fallback) {
    const auto position = value.find("px");
    if (position == std::string::npos) {
        return fallback;
    }
    try {
        return std::stof(value.substr(0, position));
    } catch (...) {
        return fallback;
    }
}

/// 读取模板里的文本框/姓名/选项样式。
///
/// 模板 SCSS 只是"作者想要的样式"的一层覆盖: 引擎默认布局用 `.TextBox_main` /
/// `.text` 的数值, 颜色和描边来自 `.outer` / `.inner`。数值单位是 2560×1440 舞台的
/// CSS px, 这里原样保留, 绘制时再由 `UiStyle::scale` 换算成导出画面像素。
void load_ui_style(const std::filesystem::path& project_root, float stage_width, UiStyle& style) {
    style.scale = stage_width / 2560.0F;
    const auto template_root = project_root / "game" / "template";
    std::string css;
    std::string text;
    if (read_text_file(template_root / "Stage" / "TextBox" / "textbox.scss", text)) {
        text = strip_css_comments(text);
        const std::string main = css_block(text, ".TextBox_main");
        style.box_left = css_px(main, "left", style.box_left);
        style.box_right = css_px(main, "right", style.box_right);
        style.box_bottom = css_px(main, "bottom", style.box_bottom);
        style.box_height = css_px(main, "min-height", style.box_height);
        style.box_radius = css_px(main, "border-radius", style.box_radius);
        style.box_color = css_color(css_value(css_block(text, ".TextBox_Background"), "background"),
                                    style.box_color);

        const std::string weight = css_value(main, "font-weight");
        if (!weight.empty()) {
            style.bold =
                weight.find("bold") != std::string::npos || css_number(weight, 400.0F) >= 600.0F;
        }
        style.letter_spacing =
            css_em_ratio(css_value(main, "letter-spacing"), style.letter_spacing);

        const std::string text_block = css_block(text, ".text");
        style.text_top = css_px(text_block, "top", style.text_top);
        style.text_margin_x = css_px(text_block, "margin-left", style.text_margin_x);
        style.text_scale = css_number(css_value(text_block, "scale"), style.text_scale);
        style.line_height = css_em_ratio(css_value(text_block, "line-height"), style.line_height);
        style.text_center =
            css_value(text_block, "align-items").find("center") != std::string::npos ||
            (text_block.find("justify-content") != std::string::npos &&
             text_block.find("center") != std::string::npos);

        // `.outer` 用 background + background-clip:text 做填充, 因此 color 往往是
        // transparent —— 这时要读 background 而不是 color, 否则会画成"只有描边"。
        const std::string outer = css_block(text, ".outer");
        std::array<float, 4> fill = css_color(css_value(outer, "background"), style.text_color);
        if (fill[3] < 0.01F) {
            fill = css_color(css_value(outer, "color"), style.text_color);
        }
        if (fill[3] > 0.01F) {
            style.text_color = fill;
        }

        const std::string inner = css_block(text, ".inner");
        if (!inner.empty()) {
            const std::string stroke_value = css_value(inner, "-webkit-text-stroke");
            const auto stroke_space = stroke_value.find_first_of(" \t");
            if (stroke_space != std::string::npos) {
                const std::string width_token = stroke_value.substr(0, stroke_space);
                const float em = css_em_ratio(width_token, -1.0F);
                style.text_stroke =
                    em >= 0.0F ? em : css_px_text(width_token, 0.1F * 52.48F) / 52.48F;
                // 颜色在 `rgb(r, g, b)` 里有空格, 必须从括号处整体解析。
                style.text_stroke_color =
                    css_color_at(stroke_value, stroke_space, style.text_stroke_color);
            }
            const auto shadow = css_tokens(css_value(inner, "text-shadow"));
            if (shadow.size() >= 3) {
                style.text_shadow_dy = css_px_text(shadow[1], style.text_shadow_dy);
                style.text_shadow_blur = css_px_text(shadow[2], style.text_shadow_blur);
                if (shadow.size() > 3) {
                    style.text_shadow_color = css_color(shadow[3], style.text_shadow_color);
                }
            }
        }

        const std::string name = css_block(text, ".TextBox_showName");
        style.name_height = css_px(name, "min-height", style.name_height);
        style.name_radius = css_px(name, "border-radius", style.name_radius);
        style.name_line_height = css_px(name, "line-height", style.name_line_height);
        style.name_scale = css_number(css_value(name, "scale"), style.name_scale);
        style.name_bg = css_color(css_value(name, "background-color"), style.name_bg);
        const auto padding = css_tokens(css_value(name, "padding"));
        if (padding.size() >= 2) {
            style.name_padding = css_em_ratio(padding[1], style.name_padding);
        }
        const std::string border = css_value(name, "border");
        if (!border.empty()) {
            const auto space = border.find_first_of(" \t");
            if (space != std::string::npos) {
                style.name_border = css_px_text(border.substr(0, space), style.name_border);
                style.name_border_color = css_color_at(border, space, style.name_border_color);
            }
        }
        const std::string box_shadow = css_value(name, "box-shadow");
        if (!box_shadow.empty()) {
            const auto shadow_tokens = css_tokens(box_shadow.substr(0, box_shadow.find('(')));
            if (shadow_tokens.size() >= 2) {
                style.name_box_shadow_dy = css_px_text(shadow_tokens[1], style.name_box_shadow_dy);
            }
            std::array<float, 4> shadow_color{0.0F, 0.0F, 0.0F, 0.3F};
            style.name_shadow_color = css_color_at(box_shadow, 0, shadow_color);
        }

        const std::string outer_name = css_block(text, ".outerName");
        std::array<float, 4> name_fill =
            css_color(css_value(outer_name, "background"), style.name_color);
        if (name_fill[3] < 0.01F) {
            name_fill = css_color(css_value(outer_name, "color"), style.name_color);
        }
        if (name_fill[3] > 0.01F) {
            style.name_color = name_fill;
        }
        const std::string inner_name = css_block(text, ".innerName");
        const auto inner_name_fill =
            css_color(css_value(inner_name, "background"), style.name_shadow_color);
        if (inner_name_fill[3] > 0.01F) {
            style.name_shadow_color = inner_name_fill;
            const float top = css_px(outer_name, "top", 2.0F);
            const float inner_top = css_px(inner_name, "top", 6.0F);
            style.name_shadow_dy = std::max(0.0F, inner_top - top);
        }
    }

    if (read_text_file(template_root / "Stage" / "Choose" / "choose.scss", css)) {
        css = strip_css_comments(css);
        const std::string item = css_block(css, ".Choose_item");
        const std::string font = css_value(item, "font-size");
        if (const auto percent = font.find('%'); percent != std::string::npos) {
            style.choice_font_ratio = css_number(font.substr(0, percent), 220.0F) / 100.0F;
        }
        const auto padding = css_tokens(css_value(item, "padding"));
        if (padding.size() >= 2) {
            style.choice_padding_y = css_px_text(padding[0], style.choice_padding_y);
            style.choice_padding_x = css_px_text(padding[1], style.choice_padding_x);
        }
        style.choice_radius = css_px(item, "border-radius", style.choice_radius);
        style.choice_background = css_color(css_value(item, "background"), style.choice_background);
        const auto color = css_color(css_value(item, "color"), style.choice_text);
        if (color[3] > 0.01F) {
            style.choice_text = color;
            style.choice_selected_text = color;
        }
        const std::string selected = css_block(css, ".Choose_item_outer");
        const auto selected_color =
            css_color(css_value(selected, "background"), style.choice_selected);
        if (selected_color[3] > 0.01F) {
            style.choice_selected = selected_color;
        }
    }
}
